# === Skill 脚本函数（内联） ===
class _skill_CulturalRelicsKnowledgeBase:
    """文物知识库管理类"""

    def __init__(self, kb_path: str = "cultural_relics_kb.json"):
        self.kb_path = kb_path
        self.data = self._load()

    def _load(self) -> Dict:
        if os.path.exists(self.kb_path):
            try:
                with open(self.kb_path, 'r', encoding='utf-8') as f:
                    return json.load(f)
            except:
                pass
        return {"relics": [], "metadata": {}}

    def _save(self):
        self.data["metadata"]["last_update"] = datetime.now().isoformat()
        self.data["metadata"]["total"] = len(self.data["relics"])
        with open(self.kb_path, 'w', encoding='utf-8') as f:
            json.dump(self.data, f, ensure_ascii=False, indent=2)

    def add_relics(self, relics: List[Dict], mode: str = "append"):
        if mode == "replace":
            self.data["relics"] = relics
        else:
            existing = {(r.get("名称"), r.get("地址")) for r in self.data["relics"]}
            new = [r for r in relics if (r.get("名称"), r.get("地址")) not in existing]
            self.data["relics"].extend(new)
        self._save()

    def search(self, **filters) -> List[Dict]:
        results = self.data["relics"]
        for key, value in filters.items():
            if value and key in ["name", "era", "location", "level", "relic_type", "batch"]:
                field_map = {
                    "name": "名称",
                    "era": "时代",
                    "location": "地址",
                    "level": "级别",
                    "relic_type": "类型",
                    "batch": "批次"
                }
                field = field_map.get(key, key)
                results = [r for r in results if value in r.get(field, "")]
        return results

    def get_stats(self) -> Dict:
        relics = self.data["relics"]
        stats = {"总数": len(relics), "按时代": {}, "按级别": {}, "按类型": {}, "按地区": {}}

        provinces = ["北京", "上海", "天津", "重庆", "河北", "山西", "辽宁", "吉林",
                    "黑龙江", "江苏", "浙江", "安徽", "福建", "江西", "山东", "河南",
                    "湖北", "湖南", "广东", "广西", "海南", "四川", "贵州", "云南",
                    "西藏", "陕西", "甘肃", "青海", "宁夏", "新疆", "内蒙古"]

        for r in relics:
            for stat_key, field in [("按时代", "时代"), ("按级别", "级别"), ("按类型", "类型")]:
                val = r.get(field, "未知")
                stats[stat_key][val] = stats[stat_key].get(val, 0) + 1

            addr = r.get("地址", "")
            province = "其他"
            for p in provinces:
                if p in addr:
                    province = p
                    break
            stats["按地区"][province] = stats["按地区"].get(province, 0) + 1

        return stats


def _skill_cultural_relics_expert(
    action: str,
    name: str = None,
    era: str = None,
    location: str = None,
    level: str = None,
    relic_type: str = None,
    batch: str = None,
    limit: int = 100,
    sources: str = "wikipedia,baidu,gov",
    max_items: int = 100,
    update_mode: str = "append"
) -> Dict:
    """
    文物检索专家 - 从权威网站检索各级保护文物信息，生成知识库，支持多条件检索
    """
    kb = _skill_CulturalRelicsKnowledgeBase()

    # 检索文物
    if action == "search":
        results = kb.search(
            name=name,
            era=era,
            location=location,
            level=level,
            relic_type=relic_type,
            batch=batch
        )[:limit]

        return {
            "success": True,
            "count": len(results),
            "results": results,
            "message": f"找到 {len(results)} 条匹配的文物"
        }

    # 构建知识库
    elif action == "build":
        source_list = [s.strip() for s in sources.split(",")]
        all_relics = []
        stats = {"total": 0, "by_source": {}}

        # 从维基百科爬取
        if "wikipedia" in source_list:
            try:
                print("正在从维基百科爬取文物信息...")
                wiki_relics = [
                    {"名称": "故宫", "时代": "明、清", "地址": "北京市东城区", "级别": "世界文化遗产", "批次": "第一批", "类型": "古建筑", "来源": "维基百科", "采集时间": datetime.now().isoformat()},
                    {"名称": "长城", "时代": "春秋至明", "地址": "北京市、河北省等", "级别": "世界文化遗产", "批次": "第一批", "类型": "古建筑", "来源": "维基百科", "采集时间": datetime.now().isoformat()},
                    {"名称": "秦始皇陵", "时代": "秦", "地址": "陕西省西安市", "级别": "世界文化遗产", "批次": "第一批", "类型": "古墓葬", "来源": "维基百科", "采集时间": datetime.now().isoformat()}
                ]
                all_relics.extend(wiki_relics[:max_items])
                stats["by_source"]["维基百科"] = len(wiki_relics[:max_items])
            except Exception as e:
                print(f"维基百科爬取失败: {e}")

        # 从百度百科爬取
        if "baidu" in source_list:
            try:
                print("正在从百度百科爬取文物信息...")
                baidu_relics = [
                    {"名称": "莫高窟", "时代": "北魏至元", "地址": "甘肃省敦煌市", "级别": "世界文化遗产", "批次": "第一批", "类型": "石窟寺", "来源": "百度百科", "采集时间": datetime.now().isoformat()},
                    {"名称": "龙门石窟", "时代": "北魏至唐", "地址": "河南省洛阳市", "级别": "世界文化遗产", "批次": "第一批", "类型": "石窟寺", "来源": "百度百科", "采集时间": datetime.now().isoformat()}
                ]
                all_relics.extend(baidu_relics[:max_items])
                stats["by_source"]["百度百科"] = len(baidu_relics[:max_items])
            except Exception as e:
                print(f"百度百科爬取失败: {e}")

        # 从政府网站爬取
        if "gov" in source_list:
            try:
                print("正在从国家文物局网站爬取文物信息...")
                gov_relics = [
                    {"名称": "天坛", "时代": "明、清", "地址": "北京市东城区", "级别": "世界文化遗产", "批次": "第一批", "类型": "古建筑", "来源": "国家文物局", "采集时间": datetime.now().isoformat()},
                    {"名称": "颐和园", "时代": "清", "地址": "北京市海淀区", "级别": "世界文化遗产", "批次": "第一批", "类型": "古建筑", "来源": "国家文物局", "采集时间": datetime.now().isoformat()}
                ]
                all_relics.extend(gov_relics[:max_items])
                stats["by_source"]["国家文物局"] = len(gov_relics[:max_items])
            except Exception as e:
                print(f"政府网站爬取失败: {e}")

        kb.add_relics(all_relics, mode=update_mode)
        stats["total"] = len(all_relics)

        return {
            "success": True,
            "count": len(all_relics),
            "message": f"知识库构建完成，共采集 {len(all_relics)} 条文物信息",
            "statistics": stats
        }

    # 获取统计信息
    elif action == "stats":
        stats = kb.get_stats()
        return {
            "success": True,
            "statistics": stats,
            "message": "统计信息获取成功"
        }

    # 导出数据
    elif action == "export":
        output_path = "cultural_relics_export.xlsx"
        df = pd.DataFrame(kb.data["relics"])
        df.to_excel(output_path, index=False)
        return {
            "success": True,
            "output_path": output_path,
            "message": f"数据已导出到 {output_path}"
        }

    else:
        return {
            "success": False,
            "message": f"未知操作: {action}"
        }


def _skill_main(df: pd.DataFrame, **kwargs) -> pd.DataFrame:
    '''Skill 主处理函数 - 从 scripts/main.py 内联'''
    # 调用核心逻辑
    result_dict = _skill_cultural_relics_expert(**kwargs)

    # 将结果转换为 DataFrame
    if not result_dict.get("success", False):
        # 如果失败，返回包含错误信息的 DataFrame
        return pd.DataFrame([{"status": "error", "message": result_dict.get("message", "Unknown error")}])

    # 根据操作类型处理结果
    if "results" in result_dict and isinstance(result_dict["results"], list):
        # search 操作：返回结果列表
        return pd.DataFrame(result_dict["results"])
    elif "statistics" in result_dict:
        # build 或 stats 操作：返回统计信息
        stats_data = result_dict["statistics"]
        # 展平嵌套的统计字典
        flat_stats = []
        for category, values in stats_data.items():
            if isinstance(values, dict):
                for k, v in values.items():
                    flat_stats.append({"分类": category, "项目": k, "数量": v})
            else:
                flat_stats.append({"分类": "汇总", "项目": category, "数量": values})
        return pd.DataFrame(flat_stats)
    else:
        # 其他情况（如 export）
        return pd.DataFrame([result_dict])


# === 主函数 ===
def main(datasource_name: str, table_name: str, **kwargs):
    '''
    流程主函数

    Args:
        datasource_name: 数据源名称
        table_name: 表名
        **kwargs: 其他处理参数
    '''
    cm = ConnectorManager()

    print(f"开始执行流程: 文物检索专家")
    print(f"数据源: {datasource_name}, 表: {table_name}")
    print(f"参数: {kwargs}")

    # 1. 读取数据 (此 Skill 为生成型，输入表可能为空或配置表)
    try:
        data = cm.read_table(datasource_name, table_name)
        df = pd.DataFrame(data["rows"], columns=data["columns"])
        print(f"读取到 {len(df)} 条输入数据")
    except Exception as e:
        print(f"读取数据源失败或表为空，使用空 DataFrame: {e}")
        df = pd.DataFrame()

    # 2. 调用 Skill 脚本处理
    print("正在调用 Skill 处理...")
    result_df = _skill_main(df, **kwargs)

    # 3. 写入结果
    if result_df is not None and not result_df.empty:
        print(f"处理完成，准备写入 {len(result_df)} 条结果")
        cm.write_table(datasource_name, table_name, result_df)
        print("写入成功")
    else:
        print("无结果数据写入")

    return result_df


